            if state['current_repo'] > state['max_repo']:
                state['max_repo'] = state['current_repo']
                state['loc'] = (frame.f_code.co_name, fn, frame.f_lineno)
                state['stack'] = get_repo_stack(frame)
    elif event=='return':
        if is_repo:
            state['current_repo'] -= 1
    return profiler

sys.setprofile(profiler)
try:
    obj.test_message_html_max_call_depth_case()
finally:
    sys.setprofile(None)

print('max_repo', state['max_repo'])
